"use client";

import "./slider.css";

import type React from "react";

import { Slider as BaseSlider } from "@base-ui/react/slider";
import { cn } from "tailwind-variants";

import { SliderContext, useSliderContext } from "./slider.context";
import { sliderVariants, type SliderVariants } from "./slider.variants";

export type SliderProps = SliderVariants & React.ComponentProps<typeof BaseSlider.Root>;

export const SliderRoot = ({ children, className, size, ...props }: SliderProps) => {
  const slots = sliderVariants({ size });

  return (
    <SliderContext.Provider value={{ slots }}>
      <BaseSlider.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseSlider.Root>
    </SliderContext.Provider>
  );
};

export type SliderLabelProps = React.ComponentProps<typeof BaseSlider.Label>;

export const SliderLabel = ({ className, ...props }: SliderLabelProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Label className={cn(slots.label(), className)} {...props} />;
};

export type SliderValueProps = React.ComponentProps<typeof BaseSlider.Value>;

export const SliderValue = ({ className, ...props }: SliderValueProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Value className={cn(slots.value(), className)} {...props} />;
};

export type SliderControlProps = React.ComponentProps<typeof BaseSlider.Control>;

export const SliderControl = ({ className, ...props }: SliderControlProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Control className={cn(slots.control(), className)} {...props} />;
};

export type SliderTrackProps = React.ComponentProps<typeof BaseSlider.Track>;

export const SliderTrack = ({ className, ...props }: SliderTrackProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Track className={cn(slots.track(), className)} {...props} />;
};

export type SliderIndicatorProps = React.ComponentProps<typeof BaseSlider.Indicator>;

export const SliderIndicator = ({ className, ...props }: SliderIndicatorProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Indicator className={cn(slots.indicator(), className)} {...props} />;
};

export type SliderThumbProps = React.ComponentProps<typeof BaseSlider.Thumb>;

export const SliderThumb = ({ className, ...props }: SliderThumbProps) => {
  const { slots } = useSliderContext();
  return <BaseSlider.Thumb className={cn(slots.thumb(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const sliderVariants = tv({
  slots: {
    root: "slider",
    label: "slider__label",
    value: "slider__value",
    control: "slider__control",
    track: "slider__track",
    indicator: "slider__indicator",
    thumb: "slider__thumb",
  },
  variants: {
    size: {
      sm: {
        track: "slider__track--sm",
        thumb: "slider__thumb--sm",
      },
      md: {
        track: "slider__track--md",
        thumb: "slider__thumb--md",
      },
      lg: {
        track: "slider__track--lg",
        thumb: "slider__thumb--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type SliderVariants = VariantProps<typeof sliderVariants>;

"use client";

import { createContext, useContext } from "react";

import { sliderVariants } from "./slider.variants";

export type SliderContext = {
  slots: ReturnType<typeof sliderVariants>;
};

export const SliderContext = createContext<SliderContext | null>(null);

export const useSliderContext = () => {
  const context = useContext(SliderContext);
  return context ?? { slots: sliderVariants() };
};

@reference "../../../app/global.css";
.slider {
  @apply grid w-full max-w-xs grid-cols-2 gap-y-1.5 text-foreground select-none;
}

.slider__label {
  @apply text-sm font-medium text-foreground;
}

.slider__value {
  @apply text-right text-sm text-muted-foreground;
}

.slider__control {
  @apply col-span-2 flex touch-none items-center py-2 select-none;
}

.slider__track {
  @apply relative w-full rounded-full bg-secondary select-none;
}

.slider__track--sm {
  @apply h-1;
}

.slider__track--md {
  @apply h-1.5;
}

.slider__track--lg {
  @apply h-2.5;
}

.slider__indicator {
  @apply rounded-full bg-primary select-none;
}

.slider__thumb {
  @apply block shrink-0 rounded-full border border-primary bg-background shadow-xs transition-colors select-none focus-visible:outline-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50;
}

.slider__thumb--sm {
  @apply size-3.5;
}

.slider__thumb--md {
  @apply size-4.5;
}

.slider__thumb--lg {
  @apply size-6;
}

import {
  SliderControl,
  SliderIndicator,
  SliderLabel,
  SliderRoot,
  SliderThumb,
  SliderTrack,
  SliderValue,
} from "./slider";

export const Slider = {
  Control: SliderControl,
  Indicator: SliderIndicator,
  Label: SliderLabel,
  Root: SliderRoot,
  Thumb: SliderThumb,
  Track: SliderTrack,
  Value: SliderValue,
};

export {
  SliderControl,
  SliderIndicator,
  SliderLabel,
  SliderRoot,
  SliderThumb,
  SliderTrack,
  SliderValue,
};

export type {
  SliderControlProps,
  SliderIndicatorProps,
  SliderLabelProps,
  SliderProps,
  SliderThumbProps,
  SliderTrackProps,
  SliderValueProps,
} from "./slider";
export { SliderContext, useSliderContext } from "./slider.context";
export { type SliderVariants, sliderVariants } from "./slider.variants";
